-- KO-225 group 5: reviewed translation of Indonesian-shaped duplicate payloads (batch 05).
update public.content_variants set body = $json${"text":"Doni, a new employee in Bandung, has a net income of Rp 4,000,000 per month. He applies the 50/30/20 rule with adjustments: Rp 2,000,000 for needs (rent, food, transport), Rp 800,000 for wants (watching movies, going out), and Rp 1,200,000 for savings and emergency funds. Every week, Doni reviews his financial record app to ensure he is not over budget.","source_ids":["7f4b83f2-8f1d-415c-9d4f-64e6284bef04"]}$json$::jsonb where id = 'fdd59825-5658-45e3-9a84-c13d1a60989f';
update public.content_variants set body = $json${"text":"Susi has savings in a bank with an interest rate of 3% per year, while inflation is 5%. The purchasing power of her savings decreases by 2% per year even though the nominal amount increases. This is called a negative real return.","source_ids":["097b62c4-9aae-4933-a870-ac74a526b8f1"]}$json$::jsonb where id = 'ffd4da83-c95a-490b-95c1-a109bf461afc';
